package com.fintrack.khmtomnenh.product.service; import com.fintrack.khmtomnenh.auth.entity.Auth; import com.fintrack.khmtomnenh.category.repository.CategoryRepository; import com.fintrack.khmtomnenh.company.entity.Company; import com.fintrack.khmtomnenh.company.repository.CompanyRepository; import com.fintrack.khmtomnenh.product.dto.ProductDto; import com.fintrack.khmtomnenh.product.entity.Product; import com.fintrack.khmtomnenh.product.repository.ProductRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class ProductService {private final ProductRepository repo;private final CompanyRepository companies;private final CategoryRepository categories;public List<Product> list(){return repo.findByActiveTrueOrderByCreatedAtDesc();}public Product get(Long id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("Product not found"));}@Transactional public Product create(ProductDto d,Auth a){Company c=company(d.companyId(),a);validateCategory(d.categoryId());return repo.save(Product.builder().company(c).categoryId(d.categoryId()).name(d.name().trim()).description(d.description()).price(d.price()).stockQuantity(d.stockQuantity()).build());}@Transactional public Product update(Long id,ProductDto d,Auth a){Product p=owned(id,a);Company c=company(d.companyId(),a);validateCategory(d.categoryId());p.setCompany(c);p.setCategoryId(d.categoryId());p.setName(d.name().trim());p.setDescription(d.description());p.setPrice(d.price());p.setStockQuantity(d.stockQuantity());return p;}@Transactional public void delete(Long id,Auth a){Product p=owned(id,a);p.setActive(false);}private Company company(Long id,Auth a){Company c=companies.findById(id).orElseThrow(()->new IllegalArgumentException("Company not found"));if(!c.getOwner().getId().equals(a.getId()))throw new AccessDeniedException("Not company owner");return c;}private void validateCategory(Long id){if(!categories.existsById(id))throw new IllegalArgumentException("Category not found");}private Product owned(Long id,Auth a){Product p=get(id);if(!p.getCompany().getOwner().getId().equals(a.getId()))throw new AccessDeniedException("Not product owner");return p;}}
